effect.shader:
const float PI = 3.14159265;
void main(){
    vec2 p=acScreenNorm-0.5; float asp=acScreenSize.x/acScreenSize.y; p.x*=asp;
    float r=length(p)+0.001;
    float ang=atan(p.y,p.x);
    float u=ang/(2.0*PI)+0.5 + twist*r;
    float v=0.25/r + acTime*speed;
    vec4 col=texture2DCv(inputImg.texture, fract(vec2(u,v)));
    col.rgb *= mix(1.0, clamp(r*2.2,0.0,1.0), fade);
    gl_FragColor=vec4(col.rgb, 1.0);
}
